    for r in range(H):
        c=0
        while c<W:
            if I[r,c]==lin:
                c0=c
                while c<W and I[r,c]==lin: c+=1
                hruns.append((r,c0,c-1))
            else: c+=1
    vrun=max(vruns,key=lambda t:t[2]-t[1]+1); hrun=max(hruns,key=lambda t:t[2]-t[1]+1)
