def comps(A,v):
    h,w=len(A),len(A[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if A[i][j]==v and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); cells=[]
                while st:
                    x,y=st.pop(); cells.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            nx,ny=x+dx,y+dy
                            if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and A[nx][ny]==v:
                                seen.add((nx,ny)); st.append((nx,ny))
                out.append(cells)
    return out
def norm(c):
    rs=[x for x,_ in c]; cs=[y for _,y in c]
    return frozenset((x-min(rs),y-min(cs)) for x,y in c)
